WITH flattened_attrs AS (SELECT id, log_ts, level, status_code, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count FROM app_logs WHERE TO_DATE(log_ts) < '2024-11-23') SELECT *, COUNT(status_code) OVER w_grp status_code_count_2h, SUM(retry_count) OVER w_hist retry_count_sum_30m, ROW_NUMBER() OVER (PARTITION BY level ORDER BY duration_sec, id) seq_no, AVG(retry_count) OVER w_grp retry_count_avg_2h FROM flattened_attrs WINDOW w_grp AS (PARTITION BY level ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW), w_hist AS (PARTITION BY level ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW);
